import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0, no messages', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n3'), null);
  assert.equal(await h.node(''), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends two RequestVotes', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
});

test('timeout refusals change nothing', async () => {
  const h = await createHost();
  const r = await h.timeout('nx');
  assert.equal(r.ok, false);
  assert.ok(!r.ok && typeof r.reason === 'string');
  assert.deepEqual(await h.inFlight(), []);
  await h.timeout('n0');
  const before = await h.inFlight();
  assert.equal((await h.timeout('n0')).ok, false);
  assert.deepEqual(await h.inFlight(), before);
  // n1 moves to term 1 as a follower: it can no longer start an election
  await h.deliver(before.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('deliverAll elects the single candidate', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.deepEqual(await h.inFlight(), []);
});

test('three candidates: nobody wins, all replies refused', async () => {
  const h = await createHost();
  for (const n of NODES) await h.timeout(n);
  await h.deliverAll();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'candidate', term: 1, votedFor: n });
});

test('a VoteReply carries term 1 and granted', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n0', to: 'n1', action: 'VoteReply', data: { term: 1, granted: false } });
});

test('delivering an unknown id does nothing', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const before = await h.inFlight();
  await h.deliver('nope');
  assert.deepEqual(await h.inFlight(), before);
});

// ── Exhaustive: every interleaving of timeouts and deliveries ────────────────
type Step = { kind: 'timeout'; node: string } | { kind: 'deliver'; key: string };

const msgKey = (m: { from: string; to: string; action: string; data: unknown }) =>
  `${m.from}>${m.to}:${m.action}:${JSON.stringify(m.data)}`;

async function snapshot(h: Host) {
  const nodes = [];
  for (const n of NODES) nodes.push(await h.node(n));
  const msgs = (await h.inFlight()).map(msgKey).sort();
  return { nodes, msgs, key: JSON.stringify([nodes, msgs]) };
}

async function replay(path: Step[]) {
  const h = await createHost();
  for (const s of path) {
    if (s.kind === 'timeout') await h.timeout(s.node);
    else await h.deliver((await h.inFlight()).find((m) => msgKey(m) === s.key)!.id);
  }
  return h;
}

test('exhaustive: at most one leader, leader holds a majority, no double votes', async () => {
  const seen = new Set<string>();
  const stack: Step[][] = [[]];
  let leaders = 0;
  while (stack.length) {
    const path = stack.pop()!;
    const h = await replay(path);
    const snap = await snapshot(h);
    if (seen.has(snap.key)) continue;
    seen.add(snap.key);
    const ls = NODES.filter((_, i) => snap.nodes[i]!.role === 'leader');
    assert.ok(ls.length <= 1, `two leaders after ${JSON.stringify(path)}`);
    if (ls.length) {
      leaders++;
      const supporters = NODES.filter((_, i) => snap.nodes[i]!.votedFor === ls[0]);
      assert.ok(supporters.length >= 2, `leader without majority after ${JSON.stringify(path)}`);
    }
    // a grant is only ever sent for the node's recorded vote
    for (const k of snap.msgs) {
      const m = k.match(/^(n\d)>(n\d):VoteReply:(.*)$/);
      if (m && JSON.parse(m[3]!).granted) {
        assert.equal(snap.nodes[NODES.indexOf(m[1]!)]!.votedFor, m[2], `inconsistent grant after ${JSON.stringify(path)}`);
      }
    }
    for (const n of NODES) stack.push([...path, { kind: 'timeout', node: n }]);
    for (const k of new Set(snap.msgs)) stack.push([...path, { kind: 'deliver', key: k }]);
  }
  assert.ok(leaders > 0);
  assert.ok(seen.size > 50);
});

