1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import createHost from '../src/host.impl.ts';
4	import type { Host } from '../src/types.ts';
5	
6	const NODES = ['n0', 'n1', 'n2'];
7	
8	test('fresh system: three followers in term 0, no messages', async () => {
9	  const h = await createHost();
10	  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null });
11	  assert.equal(await h.node('n3'), null);
12	  assert.equal(await h.node(''), null);
13	  assert.deepEqual(await h.inFlight(), []);
14	});
15	
16	test('timeout makes a candidate and sends two RequestVotes', async () => {
17	  const h = await createHost();
18	  assert.deepEqual(await h.timeout('n0'), { ok: true });
19	  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
20	  const msgs = await h.inFlight();
21	  assert.equal(msgs.length, 2);
22	  for (const m of msgs) {
23	    assert.equal(m.from, 'n0');
24	    assert.equal(m.action, 'RequestVote');
25	    assert.deepEqual(m.data, { from: 'n0', term: 1 });
26	  }
27	  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
28	});
29	
30	test('timeout refusals change nothing', async () => {
31	  const h = await createHost();
32	  const r = await h.timeout('nx');
33	  assert.equal(r.ok, false);
34	  assert.ok(!r.ok && typeof r.reason === 'string');
35	  assert.deepEqual(await h.inFlight(), []);
36	  await h.timeout('n0');
37	  const before = await h.inFlight();
38	  assert.equal((await h.timeout('n0')).ok, false);
39	  assert.deepEqual(await h.inFlight(), before);
40	  // n1 moves to term 1 as a follower: it can no longer start an election
41	  await h.deliver(before.find((m) => m.to === 'n1')!.id);
42	  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
43	  assert.equal((await h.timeout('n1')).ok, false);
44	});
45	
46	test('deliverAll elects the single candidate', async () => {
47	  const h = await createHost();
