import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

const NODES = ['n0', 'n1', 'n2'];

test('fresh system: three followers in term 0, no messages', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.equal(await h.node(''), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends two RequestVotes', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
});

test('timeout refusals change nothing', async () => {
  const h = await createHost();
  const r = await h.timeout('nx');
  assert.equal(r.ok, false);
  assert.ok(!r.ok && typeof r.reason === 'string');
  assert.deepEqual(await h.inFlight(), []);
  await h.timeout('n0');
  const before = await h.inFlight();
  assert.equal((await h.timeout('n0')).ok, false);
  assert.deepEqual(await h.inFlight(), before);
  // n1 moves to term 1 as a follower: it can no longer start an election
  await h.deliver(before.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('deliverAll elects the single candidate', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.inFlight(), []);
});

test('three candidates: nobody wins, all replies refused', async () => {
  const h = await createHost();
  for (const n of NODES) await h.timeout(n);
  await h.deliverAll();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'candidate', term: 1, votedFor: n, leader: null });
});

test('the new leader sends Leader to the other two nodes', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const leaders = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(leaders.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of leaders) {
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
});

test('Leader moves a term-0 node to term 1 without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h.timeout('n2')).ok, false);
  // the stale RequestVote still arrives: n2 has not voted, so it grants; n0 is already leader and ignores it
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('Leader makes a candidate step down, keeping its vote for itself', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('a VoteReply carries term 1 and granted', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n0', to: 'n1', action: 'VoteReply', data: { term: 1, granted: false } });
});

test('delivering an unknown id does nothing', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const before = await h.inFlight();
  await h.deliver('nope');
  assert.deepEqual(await h.inFlight(), before);
});

