test('Leader makes a candidate step down, keeping its vote for itself', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
