test('a VoteReply carries term 1 and granted', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n0', to: 'n1', action: 'VoteReply', data: { term: 1, granted: false } });
