    name: 'granted-reply-matches-the-voters-vote',
    pred: (s) => s.net.every((m) => m.action !== 'VoteReply' || !m.granted || s.nodes[m.from].votedFor === m.to),
  },
  {
    name: 'term-0-nodes-have-not-voted',
    pred: (s) => NODES.every((n) => s.nodes[n].term !== 0 || (s.nodes[n].votedFor === null && s.nodes[n].role === 'follower')),
  },
  {
    name: 'terms-are-0-or-1',
    pred: (s) => NODES.every((n) => s.nodes[n].term === 0 || s.nodes[n].term === 1),
