// Negative control: each mutant of spec/election.cjs breaks one rule of the
// brief; the checker must find a violation for every one of them.
// Run: node spec/controls/run-mutants.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { check, loadSpec } from '../../tools/polygraph/scripts/check.mjs';
import * as invariants from '../invariants.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const src = readFileSync(join(here, '..', 'election.cjs'), 'utf-8');
const contract = JSON.parse(readFileSync(join(here, '..', 'contract.json'), 'utf-8'));
const outDir = join(here, 'out');
mkdirSync(outDir, { recursive: true });

// [name, find, replace, expectCaught]. expectCaught=false marks a mutant that is
// behaviorally EQUIVALENT under this protocol (no state can tell it apart).
const MUTANTS = [
  ['grant-to-anyone', "if (s.role === 'follower' && s.votedFor === null) {", 'if (true) {', true],
  ['candidate-grants', "if (s.role === 'follower' && s.votedFor === null) {", "if (s.role !== 'leader') {", true],
  ['leader-at-timeout', "{ role: 'candidate', term: 1, votedFor: id, votes: [id] }", "{ role: 'leader', term: 1, votedFor: id, votes: [id] }", true],
  ['count-refused-replies', 'm.granted !== true ||', '', true],
  ['timeout-from-term-1', "if (s.term !== 0) return reject('not-in-term-0');", '', true],
  // a candidate counts only on a reply, so it already holds 2 votes when it can first win
  ['leader-on-one-vote', 'const MAJORITY = 2;', 'const MAJORITY = 1;', false],
  // each voter sends a candidate at most one grant: there is never a duplicate to count
  ['double-count-a-voter', ' || s.votes.includes(m.from)', '', false],
];

let failed = 0;
for (const [name, from, to, expectCaught] of MUTANTS) {
  if (!src.includes(from)) { console.log(`✗ ${name}: pattern not found`); failed++; continue; }
  const file = join(outDir, `${name}.cjs`);
  writeFileSync(file, src.replace(from, to));
  const r = check({ specModule: loadSpec(file), contract, invariants, maxStates: 3000 });
  const hit = [...new Set(r.violations.map((v) => v.invariant))];
  const caught = !r.error && hit.length > 0;
  const okay = caught === expectCaught;
  if (!okay) failed++;
  console.log(`${okay ? '✓' : '✗'} ${name}: ${caught ? `caught by ${hit.join(', ')}` : `not caught${expectCaught ? ' (UNEXPECTED)' : ' (equivalent mutant, as expected)'} ${r.error ?? ''}`}`);
}
process.exit(failed ? 1 : 0);

