// Capture real execution traces from src/host.impl.ts, one NDJSON file per
// scenario, in the spec's observable state { nodes, net }.
// Run: node spec/capture.mjs   (writes spec/traces/*.ndjson)
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import createHost, { inspectNodes } from '../src/host.impl.ts';

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, 'traces');
mkdirSync(outDir, { recursive: true });

const NODES = ['n0', 'n1', 'n2'];
const key = (m) => `${m.from}>${m.to}:${m.action}`;

async function observe(h) {
  const net = (await h.inFlight())
    .map((m) => (m.action === 'RequestVote'
      ? { from: m.from, to: m.to, action: m.action, term: m.data.term }
      : { from: m.from, to: m.to, action: m.action, term: m.data.term, granted: m.data.granted }))
    .sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
  return { nodes: inspectNodes.get(h)(), net };
}

// deterministic PRNG (mulberry32)
const rng = (seed) => () => {
  seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

async function scenario(name, seed, steps) {
  const rand = rng(seed);
  const pick = (xs) => xs[Math.floor(rand() * xs.length)];
  const h = await createHost();
  const lines = [];
  for (let i = 0; i < steps; i++) {
    const pre = await observe(h);
    const inFlight = await h.inFlight();
    const r = rand();
    let action, data;
    if (inFlight.length && r < 0.6) {
      const m = pick(inFlight);
      action = 'DELIVER'; data = { from: m.from, to: m.to, action: m.action };
      await h.deliver(m.id);
    } else if (r < 0.9) {
      action = 'TIMEOUT'; data = { node: pick([...NODES, 'nx']) };
      await h.timeout(data.node);
    } else {
      // a delivery of a message that is not in transit: a no-op
      const cand = { from: pick(NODES), to: pick(NODES), action: pick(['RequestVote', 'VoteReply']) };
      if (inFlight.some((m) => key(m) === key(cand))) continue;
      action = 'DELIVER'; data = cand;
      await h.deliver('not-in-transit');
    }
    lines.push(JSON.stringify({ pre, action, data, post: await observe(h) }));
  }
  writeFileSync(join(outDir, `${name}.ndjson`), lines.join('\n') + '\n');
  return lines.length;
}

let total = 0;
for (let s = 1; s <= 40; s++) total += await scenario(`random-${String(s).padStart(2, '0')}`, s, 25);
console.log(`captured ${total} windows in 40 traces`);

