  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const leaders = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(leaders.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of leaders) {
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
});

test('Leader moves a term-0 node to term 1 without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h.timeout('n2')).ok, false);
  // the stale RequestVote still arrives: n2 has not voted, so it grants; n0 is already leader and ignores it
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('Leader makes a candidate step down, keeping its vote for itself', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('giveUp: a candidate becomes a follower in the same term, keeping its vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  // the RequestVotes are still in transit; the granted replies are ignored
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('giveUp: a node that gave up grants no other vote, so another candidate can still win', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  await h.giveUp('n0');
  await h.deliver((await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
  await h.deliverAll();
  // n2 voted for whichever RequestVote reached it first: n1 leads only if it got n2's vote
  const n1 = (await h.node('n1'))!;
  const n2 = (await h.node('n2'))!;
  if (n2.votedFor === 'n1') {
    assert.equal(n1.role, 'leader');
    assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n1' });
  } else {
    assert.equal(n1.role, 'candidate');
  }
});

test('giveUp is refused for a follower, a leader, or an unknown id, and changes nothing', async () => {
  const h = await createHost();
  for (const id of ['n0', 'nx', '']) {
    const r = await h.giveUp(id);
    assert.equal(r.ok, false);
    assert.ok(!r.ok && typeof r.reason === 'string');
  }
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null, leader: null });
  await h.timeout('n0');
  await h.deliverAll();
  const msgs = await h.inFlight();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('n1')).ok, false);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.inFlight(), msgs);
  // giving up twice: the second is refused
  const h2 = await createHost();
  await h2.timeout('n2');
  assert.equal((await h2.giveUp('n2')).ok, true);
  assert.equal((await h2.giveUp('n2')).ok, false);
});

test('a VoteReply carries term 1 and granted', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  const rv = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n0')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { id: reply.id, from: 'n0', to: 'n1', action: 'VoteReply', data: { term: 1, granted: false } });
});

test('delivering an unknown id does nothing', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const before = await h.inFlight();
  await h.deliver('nope');
  assert.deepEqual(await h.inFlight(), before);
});

// ── Exhaustive: every interleaving of timeouts and deliveries ────────────────
type Step = { kind: 'timeout' | 'giveUp'; node: string } | { kind: 'deliver'; key: string };

const msgKey = (m: { from: string; to: string; action: string; data: unknown }) =>
  `${m.from}>${m.to}:${m.action}:${JSON.stringify(m.data)}`;

async function snapshot(h: Host) {
  const nodes = [];
  for (const n of NODES) nodes.push(await h.node(n));
  const msgs = (await h.inFlight()).map(msgKey).sort();
  return { nodes, msgs, key: JSON.stringify([nodes, msgs]) };
}

async function replay(path: Step[]) {
  const h = await createHost();
  for (const s of path) {
    if (s.kind === 'timeout') await h.timeout(s.node);
    else if (s.kind === 'giveUp') await h.giveUp(s.node);
    else await h.deliver((await h.inFlight()).find((m) => msgKey(m) === s.key)!.id);
  }
  return h;
}

test('exhaustive: at most one leader, leader holds a majority, no double votes', async () => {
  const seen = new Set<string>();
  type Frame = { path: Step[]; parent: Awaited<ReturnType<typeof snapshot>>['nodes'] | null };
  const stack: Frame[] = [{ path: [], parent: null }];
  let leaders = 0;
  let announced = 0;
  while (stack.length) {
    const { path, parent } = stack.pop()!;
    const h = await replay(path);
    const snap = await snapshot(h);
    // no node changes a vote it cast in its term (checked on every edge, even into seen states)
    if (parent) {
      NODES.forEach((n, i) => {
        const a = parent[i]!, b = snap.nodes[i]!;
        if (a.votedFor !== null && a.term === b.term) assert.equal(b.votedFor, a.votedFor, `${n} voted twice after ${JSON.stringify(path)}`);
      });
    }
    if (seen.has(snap.key)) continue;
    seen.add(snap.key);
    const ls = NODES.filter((_, i) => snap.nodes[i]!.role === 'leader');
    assert.ok(ls.length <= 1, `two leaders after ${JSON.stringify(path)}`);
    if (ls.length) {
      leaders++;
      const supporters = NODES.filter((_, i) => snap.nodes[i]!.votedFor === ls[0]);
      assert.ok(supporters.length >= 2, `leader without majority after ${JSON.stringify(path)}`);
      assert.equal(snap.nodes[NODES.indexOf(ls[0]!)]!.leader, ls[0], 'a leader knows itself');
    }
    // a known leader is the real leader, and no Leader message is ever addressed to a leader
    NODES.forEach((n, i) => {
      const known = snap.nodes[i]!.leader;
      if (known !== null) {
        assert.deepEqual(ls, [known], `${n} knows a leader that does not lead after ${JSON.stringify(path)}`);
        if (known !== n) announced++;
      }
    });
    for (const k of snap.msgs) {
      const m = k.match(/^(n\d)>(n\d):Leader:/);
      if (m) {
        assert.deepEqual(ls, [m[1]], `Leader from a non-leader after ${JSON.stringify(path)}`);
        assert.notEqual(m[2], m[1]);
      }
    }
    // a grant is only ever sent for the node's recorded vote
    for (const k of snap.msgs) {
      const m = k.match(/^(n\d)>(n\d):VoteReply:(.*)$/);
      if (m && JSON.parse(m[3]!).granted) {
        assert.equal(snap.nodes[NODES.indexOf(m[1]!)]!.votedFor, m[2], `inconsistent grant after ${JSON.stringify(path)}`);
      }
    }
    for (const n of NODES) stack.push({ path: [...path, { kind: 'timeout', node: n }], parent: snap.nodes });
    for (const k of new Set(snap.msgs)) stack.push({ path: [...path, { kind: 'deliver', key: k }], parent: snap.nodes });
  }
  assert.ok(leaders > 0);
  assert.ok(announced > 0);
  assert.ok(seen.size > 50);
});

