'use strict';
// SAM v2 strict-profile spec of the election core (src/core.ts + the network in
// src/host.impl.ts). State: every node's {role, term, votedFor, leader, votes}
// and the bag of messages in transit. A message is identified by (from, to,
// action): each node sends at most one RequestVote, one VoteReply and one
// Leader to each peer.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const follower0 = () => ({ role: 'follower', term: 0, votedFor: null, leader: null, votes: [] });
const INITIAL_STATE = {
  nodes: { n0: follower0(), n1: follower0(), n2: follower0() },
  net: [],
};

const msgKey = (m) => `${m.from}>${m.to}:${m.action}`;
const sortNet = (net) => [...net].sort((a, b) => (msgKey(a) < msgKey(b) ? -1 : msgKey(a) > msgKey(b) ? 1 : 0));
const without = (net, m) => net.filter((x) => x !== m);

const DELIVER_DOMAIN = [];
for (const from of NODES) for (const to of NODES) for (const action of ['RequestVote', 'VoteReply', 'Leader'])
  DELIVER_DOMAIN.push({ from, to, action });

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      nodes: { type: 'object' },
      net: { type: 'array' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string', required: true } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'nx' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: {
          from: { type: 'string', required: true },
          to: { type: 'string', required: true },
          action: { type: 'string', required: true },
        },
        domain: DELIVER_DOMAIN,
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next }) => {
        const id = proposal.node;
        if (!NODES.includes(id)) return reject('unknown-node');
        const s = model.nodes[id];
        if (s.role !== 'follower') return reject('not-a-follower');
        if (s.term !== 0) return reject('not-in-term-0');
        next.nodes = { ...model.nodes, [id]: { role: 'candidate', term: 1, votedFor: id, leader: null, votes: [id] } };
        const sent = NODES.filter((n) => n !== id).map((to) => ({ from: id, to, action: 'RequestVote', term: 1 }));
        next.net = sortNet([...model.net, ...sent]);
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const m = model.net.find((x) => x.from === proposal.from && x.to === proposal.to && x.action === proposal.action);
        if (!m) return reject('no-such-message');
        const id = m.to;
        const s = model.nodes[id];
        if (m.action === 'RequestVote') {
          const candidate = m.from;
          let state = s;
          let granted = false;
          if (m.term === 1 && candidate !== id) {
            if (s.term < 1) {
              state = { role: 'follower', term: 1, votedFor: candidate, leader: null, votes: [] };
              granted = true;
            } else if (s.term === 1) {
              if (s.role === 'follower' && s.votedFor === null) {
                state = { ...s, votedFor: candidate };
                granted = true;
              } else if (s.role === 'follower' && s.votedFor === candidate) {
                granted = true;
              }
            }
          }
          next.nodes = { ...model.nodes, [id]: state };
          next.net = sortNet([...without(model.net, m), { from: id, to: candidate, action: 'VoteReply', term: 1, granted }]);
          return;
        }
        if (m.action === 'Leader') {
          // a term-0 node joins term 1 without voting; a candidate steps down keeping its vote; a leader ignores it
          next.net = without(model.net, m);
          if (m.term !== 1 || s.role === 'leader') {
            unchanged('nodes');
            return;
          }
          const state = s.term < 1
            ? { role: 'follower', term: 1, votedFor: null, leader: m.from, votes: [] }
            : { ...s, role: 'follower', leader: m.from };
          next.nodes = { ...model.nodes, [id]: state };
          return;
        }
        // VoteReply: a candidate counts a granted reply for its term; anything else is consumed and ignored
        if (s.role !== 'candidate' || m.granted !== true || m.term !== s.term || s.votes.includes(m.from)) {
          next.net = without(model.net, m);
          unchanged('nodes');
          return;
        }
        const votes = [...s.votes, m.from].sort();
        if (votes.length < MAJORITY) {
          next.net = without(model.net, m);
          next.nodes = { ...model.nodes, [id]: { ...s, votes } };
          return;
        }
        // elected: lead, and announce to the others
        next.nodes = { ...model.nodes, [id]: { ...s, votes, role: 'leader', leader: id } };
        const announce = NODES.filter((n) => n !== id).map((to) => ({ from: id, to, action: 'Leader', term: 1 }));
        next.net = sortNet([...without(model.net, m), ...announce]);
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(JSON.parse(JSON.stringify(INITIAL_STATE))); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

