// Rules the brief requires, as predicates over the spec state { nodes, net }.
const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leaders = (s) => NODES.filter((n) => s.nodes[n].role === 'leader');
const supporters = (s, c) => NODES.filter((n) => s.nodes[n].term === 1 && s.nodes[n].votedFor === c);

export const stateInvariants = [
  {
    name: 'at-most-one-leader-per-term',
    pred: (s) => leaders(s).length <= 1,
  },
  {
    name: 'leader-holds-majority-of-votes',
    pred: (s) => leaders(s).every((l) => supporters(s, l).length >= MAJORITY),
  },
  {
    name: 'counted-votes-are-real-votes',
    // every vote a candidate/leader counts was actually cast for it by that node
    pred: (s) => NODES.every((c) => s.nodes[c].votes.every((v) => s.nodes[v].term === 1 && s.nodes[v].votedFor === c)),
  },
  {
    name: 'candidates-and-leaders-voted-for-themselves',
    pred: (s) => NODES.every((n) => s.nodes[n].role === 'follower' || (s.nodes[n].term === 1 && s.nodes[n].votedFor === n)),
  },
  {
    name: 'granted-reply-matches-the-voters-vote',
    pred: (s) => s.net.every((m) => m.action !== 'VoteReply' || !m.granted || s.nodes[m.from].votedFor === m.to),
  },
  {
    name: 'term-0-nodes-have-not-voted-nor-learned-a-leader',
    pred: (s) => NODES.every((n) => s.nodes[n].term !== 0 || (s.nodes[n].votedFor === null && s.nodes[n].role === 'follower' && s.nodes[n].leader === null)),
  },
  {
    name: 'a-known-leader-is-the-leader',
    pred: (s) => NODES.every((n) => s.nodes[n].leader === null || s.nodes[s.nodes[n].leader].role === 'leader'),
  },
  {
    name: 'a-leader-knows-itself',
    pred: (s) => leaders(s).every((l) => s.nodes[l].leader === l),
  },
  {
    name: 'only-a-candidate-or-follower-without-a-leader-lacks-one',
    // whoever knows a leader is a follower of it or the leader itself
    pred: (s) => NODES.every((n) => s.nodes[n].leader === null || s.nodes[n].role === 'follower' || s.nodes[n].leader === n),
  },
  {
    name: 'term-1-without-a-vote-means-a-leader-was-announced',
    pred: (s) => NODES.every((n) => s.nodes[n].term !== 1 || s.nodes[n].votedFor !== null || s.nodes[n].leader !== null),
  },
  {
    name: 'the-leader-is-announced-to-every-other-node',
    // each other node knows the leader or has its Leader message in transit
    pred: (s) => leaders(s).every((l) => NODES.every((n) => n === l || s.nodes[n].leader === l
      || s.net.some((m) => m.action === 'Leader' && m.from === l && m.to === n))),
  },
  {
    name: 'leader-messages-come-from-the-leader-and-never-reach-a-leader',
    pred: (s) => s.net.every((m) => m.action !== 'Leader' || (s.nodes[m.from].role === 'leader' && m.to !== m.from && s.nodes[m.to].role !== 'leader')),
  },
  {
    name: 'a-follower-counts-no-votes',
    pred: (s) => NODES.every((n) => s.nodes[n].role !== 'follower' || s.nodes[n].votes.length === 0),
  },
  {
    name: 'terms-are-0-or-1',
    pred: (s) => NODES.every((n) => s.nodes[n].term === 0 || s.nodes[n].term === 1),
  },
];

