    name: 'a-term-1-follower-stays-a-follower',
    // once a follower in term 1 (voter, stepped down, or gave up), no late VoteReply makes it candidate or leader
    pred: (pre, _a, _d, post) => NODES.every((n) => pre.nodes[n].role !== 'follower' || pre.nodes[n].term !== 1 || post.nodes[n].role === 'follower'),
  },
  {
    name: 'a-known-leader-never-changes-in-the-term',
    pred: (pre, _a, _d, post) =>
      NODES.every((n) => pre.nodes[n].leader === null || (post.nodes[n].term === pre.nodes[n].term && post.nodes[n].leader === pre.nodes[n].leader)),
  },
  {
    name: 'at-most-one-election-per-node',
    // only a term-0 follower may become a candidate
    pred: (pre, _a, _d, post) =>
      NODES.every((n) => post.nodes[n].role !== 'candidate' || pre.nodes[n].role === 'candidate' || (pre.nodes[n].term === 0 && pre.nodes[n].role === 'follower')),
  },
];

