const here = dirname(fileURLToPath(import.meta.url));
const src = readFileSync(join(here, '..', 'election.cjs'), 'utf-8');
const contract = JSON.parse(readFileSync(join(here, '..', 'contract.json'), 'utf-8'));
const outDir = join(here, 'out');
mkdirSync(outDir, { recursive: true });

// [name, find, replace, expectCaught]. expectCaught=false marks a mutant that is
// behaviorally EQUIVALENT under this protocol (no state can tell it apart).
const MUTANTS = [
  ['grant-to-anyone', "if (s.role === 'follower' && s.votedFor === null) {", 'if (true) {', true],
  ['candidate-grants', "if (s.role === 'follower' && s.votedFor === null) {", "if (s.role !== 'leader') {", true],
  ['leader-at-timeout', "{ role: 'candidate', term: 1, votedFor: id, leader: null, votes: [id] }", "{ role: 'leader', term: 1, votedFor: id, leader: id, votes: [id] }", true],
  ['count-refused-replies', 'm.granted !== true ||', '', true],
  ['timeout-from-term-1', "if (s.term !== 0) return reject('not-in-term-0');", '', true],
  ['leader-message-casts-a-vote', "{ role: 'follower', term: 1, votedFor: null, leader: m.from, votes: [] }", "{ role: 'follower', term: 1, votedFor: m.from, leader: m.from, votes: [] }", true],
  ['step-down-drops-own-vote', "{ ...s, role: 'follower', leader: m.from, votes: [] }", "{ ...s, role: 'follower', votedFor: null, leader: m.from, votes: [] }", true],
  ['step-down-keeps-candidacy', "{ ...s, role: 'follower', leader: m.from, votes: [] }", '{ ...s, leader: m.from }', true],
  ['step-down-keeps-counting', "{ ...s, role: 'follower', leader: m.from, votes: [] }", "{ ...s, role: 'follower', leader: m.from }", true],
  ['no-announcement', "const announce = NODES.filter((n) => n !== id)", 'const announce = [].filter((n) => n !== id)', true],
  ['leader-forgets-itself', "role: 'leader', leader: id }", "role: 'leader', leader: null }", true],
  ['give-up-drops-vote', "next.nodes = { ...model.nodes, [id]: { ...s, role: 'follower', votes: [] } };", "next.nodes = { ...model.nodes, [id]: { ...s, role: 'follower', votedFor: null, votes: [] } };", true],
  ['give-up-keeps-counting', "next.nodes = { ...model.nodes, [id]: { ...s, role: 'follower', votes: [] } };", "next.nodes = { ...model.nodes, [id]: { ...s, role: 'follower' } };", true],
  ['give-up-from-leader', "if (s.role !== 'candidate') return reject('not-a-candidate');", "if (s.role === 'follower') return reject('not-a-candidate');", true],
  ['late-reply-revives', "if (s.role !== 'candidate' || m.granted !== true", "if (s.role === 'leader' || m.granted !== true", true],
